import com.prometheus.clq.model.Question

/**
 * Questions Expansion 4 — Culture Mondiale
 * Tech, Nature, Science, Mythologie, Histoire, Philosophie
 * ~150 questions (Traduites en Français)
 */
object QuestionsExpansion4 {
    fun get(): List<Question> = listOf(
        // TECH (30151-30175) - 25 questions
        Question(30153, "Quelle plateforme de médias sociaux a été fondée par Mark Zuckerberg ?", listOf("Facebook", "Twitter", "Instagram", "TikTok"), 0, "Tech", Difficulty.EASY, explanation = "Mark Zuckerberg a cofondé Facebook en 2004 depuis sa chambre d'université à Harvard, initialement comme un réseau social pour les étudiants."),
        Question(30154, "En quelle année le premier iPhone a-t-il été lancé ?", listOf("2007", "2005", "2009", "2010"), 0, "Tech", Difficulty.EASY, explanation = "Steve Jobs a présenté le premier iPhone le 9 janvier 2007, et il a été mis en vente aux États-Unis le 29 juin de la même année."),
        Question(30155, "Quelle console de jeu a été créée par Nintendo en 1983 ?", listOf("NES", "SNES", "N64", "GameCube"), 0, "Tech", Difficulty.EASY, explanation = "La NES (Nintendo Entertainment System) est sortie en 1983 au Japon sous le nom de Famicom, relançant l'industrie du jeu vidéo après le krach de 1983."),
        Question(30156, "Que signifie 'GPU' ?", listOf("Unité de Traitement Graphique", "Mise à jour du Traitement Général", "Utilitaire de Plateforme Mondiale", "Unité de Puissance Graphique"), 0, "Tech", Difficulty.EASY, explanation = "GPU est l'acronyme de Graphics Processing Unit, traduit en français par Unité de Traitement Graphique. Ce composant électronique est spécialisé dans le calcul rapide d'images et d'animations, essentiel pour les jeux vidéo et le rendu 3D."),
        Question(30157, "Qui est connu comme le père de l'intelligence artificielle ?", listOf("Alan Turing", "Geoffrey Hinton", "Yann LeCun", "Yoshua Bengio"), 0, "Tech", Difficulty.MEDIUM, explanation = "Alan Turing a posé les bases théoriques de l'IA avec son test de Turing et ses travaux sur la machine universelle, publiés dans les années 1950."),
        Question(30158, "Quelle crypto-monnaie a été créée par Satoshi Nakamoto ?", listOf("Bitcoin", "Ethereum", "Dogecoin", "Ripple"), 0, "Tech", Difficulty.MEDIUM, explanation = "Bitcoin a été lancé en 2009 par une personne ou un groupe sous le pseudonyme Satoshi Nakamoto, dont l'identité réelle reste inconnue."),
        Question(30159, "Que signifie 'VR' dans les jeux ?", listOf("Réalité Virtuelle", "Rendu Vertical", "Résolution Vectorielle", "Débit Variable"), 0, "Tech", Difficulty.MEDIUM, explanation = "VR signifie Réalité Virtuelle, une technologie qui plonge l'utilisateur dans un environnement numérique immersif via un casque."),
        Question(30160, "Quelle entreprise a popularisé l'écran tactile des smartphones ?", listOf("Apple", "Samsung", "Nokia", "BlackBerry"), 0, "Tech", Difficulty.MEDIUM, explanation = "Apple a popularisé l'écran tactile capacitif avec l'iPhone en 2007, rendant cette technologie intuitive et accessible au grand public."),
        Question(30161, "Après quel nom Python (le langage de programmation) a-t-il été nommé ?", listOf("Monty Python", "Une espèce de serpent", "Un concept de programmation", "Une créature mythique"), 0, "Tech", Difficulty.MEDIUM, explanation = "Guido van Rossum, le créateur de Python, a nommé le langage en hommage à la troupe comique britannique Monty Python, dont il était fan."),
        Question(30162, "Quel géant technologique a acquis Instagram en 2012 ?", listOf("Facebook", "Google", "Amazon", "Microsoft"), 0, "Tech", Difficulty.MEDIUM, explanation = "Facebook a racheté Instagram en 2012 pour environ 1 milliard de dollars, renforçant ainsi sa présence dans le partage de photos mobiles."),
        Question(30164, "Qui a développé le World Wide Web ?", listOf("Tim Berners-Lee", "Vint Cerf", "Jon Postel", "Lawrence Roberts"), 0, "Tech", Difficulty.HARD, explanation = "Tim Berners-Lee a inventé le World Wide Web en 1989 alors qu'il travaillait au CERN, proposant un système de navigation par hyperliens pour partager des informations entre chercheurs."),
        Question(30165, "Quel est l'objectif principal de la technologie blockchain ?", listOf("Enregistrement décentralisé des données", "Amélioration de la vitesse Internet", "Refroidissement des ordinateurs", "Optimisation du stockage"), 0, "Tech", Difficulty.HARD, explanation = "La blockchain est conçue pour stocker des informations de manière décentralisée, répartie sur un réseau d'ordinateurs, garantissant transparence et sécurité sans autorité centrale."),
        Question(30166, "Quel jeu esport a les plus grands prix mondiaux ?", listOf("Dota 2", "League of Legends", "Counter-Strike", "Starcraft"), 0, "Tech", Difficulty.HARD, explanation = "Dota 2 détient le record des plus gros prize pools de l'esport, notamment grâce à son système de financement participatif via le Battle Pass pour The International."),
        Question(30167, "Que signifie 'API' en programmation ?", listOf("Interface de Programmation d'Applications", "Intégration de Processus Automatisés", "Interface de Protocole Avancé", "Entrée de Traitement Algorithmique"), 0, "Tech", Difficulty.HARD, explanation = "API signifie Application Programming Interface, soit Interface de Programmation d'Applications en français. C'est un ensemble de règles qui permet à des logiciels de communiquer entre eux."),
        Question(30168, "Quelle entreprise informatique quantique IBM a-t-elle établie ?", listOf("IBM", "Google", "IonQ", "D-Wave"), 0, "Tech", Difficulty.HARD, explanation = "IBM a fondé sa propre division d'informatique quantique, nommée IBM Quantum, en 2015 pour développer des ordinateurs quantiques et des services cloud associés."),
        Question(30169, "En quelle année la première webcam a-t-elle été créée à l'Université Cambridge ?", listOf("1991", "1995", "1998", "2001"), 0, "Tech", Difficulty.HARD, explanation = "La première webcam fut installée en 1991 à l'Université de Cambridge pour surveiller une machine à café, permettant aux chercheurs de vérifier à distance s'il y avait du café disponible."),
        Question(30170, "Quel milliardaire de la technologie a fondé SpaceX ?", listOf("Elon Musk", "Jeff Bezos", "Bill Gates", "Mark Zuckerberg"), 0, "Tech", Difficulty.HARD, explanation = "Elon Musk a fondé SpaceX en 2002 avec l'objectif de réduire les coûts d'accès à l'espace et de permettre la colonisation de Mars."),
        Question(30171, "Que signifie 'NVIDIA' ?", listOf("Pas d'Architecture d'Affichage Vidéo", "Pas un GPU traditionnel", "Entrée Vidéo Réseau", "Appareil d'Interface Vidéo Suivant"), 3, "Tech", Difficulty.EXPERT, explanation = "NVIDIA est un acronyme pour \"Next Video Interface Device\", choisi lors de la création de l'entreprise en 1993 par Jensen Huang, Chris Malachowsky et Curtis Priem."),
        Question(30172, "Quel framework d'apprentissage profond est maintenu par Facebook AI Research ?", listOf("PyTorch", "TensorFlow", "Keras", "Caffe"), 0, "Tech", Difficulty.EXPERT, explanation = "PyTorch est un framework open source d'apprentissage profond développé et maintenu par Facebook AI Research (FAIR), lancé en 2016."),
        Question(30173, "Quel est le nom du processeur quantique de Google annoncé en 2019 ?", listOf("Sycamore", "Willow", "Bristlecone", "Aspen"), 0, "Tech", Difficulty.EXPERT, explanation = "Sycamore est le processeur quantique de Google qui a démontré en 2019 la suprématie quantique en effectuant un calcul spécifique en 200 secondes, là où un supercalculateur classique aurait mis des milliers d'années."),
        Question(30174, "Quel terme de cybersécurité désigne une vulnérabilité inconnue du fournisseur ?", listOf("Zero-day", "Black-hat", "White-hat", "Red-team"), 0, "Tech", Difficulty.EXPERT, explanation = "Le terme zero-day désigne une faille de sécurité qui n'a pas encore été découverte ou corrigée par le développeur, laissant aux attaquants un temps d'avance pour l'exploiter avant qu'un correctif ne soit disponible."),
        Question(30175, "Quelle est la vitesse théorique maximale de l'USB 3.2 ?", listOf("20 Gbps", "10 Gbps", "5 Gbps", "480 Mbps"), 0, "Tech", Difficulty.EXPERT, explanation = "L'USB 3.2 Gen 2x2 utilise deux voies de 10 Gbps chacune pour atteindre un débit théorique de 20 Gbps, soit le double de l'USB 3.2 Gen 2."),

        // NATURE (30176-30200) - 25 questions
        Question(30176, "Quel est le plus grand animal du monde ?", listOf("Baleine bleue", "Éléphant d'Afrique", "Girafe", "Hippopotame"), 0, "Nature", Difficulty.EASY, explanation = "La baleine bleue peut atteindre 30 mètres de long et peser jusqu'à 200 tonnes, ce qui en fait le plus grand animal connu sur Terre."),
        Question(30177, "Combien de pattes une pieuvre a-t-elle ?", listOf("8", "6", "10", "12"), 0, "Nature", Difficulty.EASY, explanation = "Les pieuvres sont des céphalopodes caractérisés par huit bras, d'où leur nom commun de poulpe. Ces bras sont munis de ventouses et leur permettent de se déplacer et de capturer leurs proies."),
        Question(30179, "Quel est le plus grand océan de la Terre ?", listOf("Pacifique", "Atlantique", "Indien", "Arctique"), 0, "Nature", Difficulty.EASY, explanation = "L'océan Pacifique est le plus grand océan de la Terre, couvrant environ 165 millions de kilomètres carrés, soit plus du tiers de la surface de la planète."),
        Question(30180, "Combien d'espèces de manchots existent ?", listOf("18", "10", "25", "30"), 0, "Nature", Difficulty.EASY, explanation = "Il existe 18 espèces de manchots reconnues scientifiquement, toutes vivant dans l'hémisphère sud, des côtes de l'Antarctique aux îles tempérées comme les Galápagos."),
        Question(30182, "Quel est le régime alimentaire principal d'un panda géant ?", listOf("Bambou", "Viande", "Poisson", "Fruit"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le panda géant est un mammifère herbivore dont l'alimentation est constituée à 99 % de bambou, malgré son appartenance à l'ordre des carnivores."),
        Question(30183, "Quel est le plus grand volcan actif du monde ?", listOf("Mauna Loa", "Mont Merapi", "Krakatoa", "Popocatépetl"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le Mauna Loa, situé à Hawaï, est le plus grand volcan actif du monde en volume et en superficie, avec une éruption majeure en 2022."),
        Question(30184, "Quel pourcentage de l'oxygène terrestre est produit par les océans ?", listOf("50-70%", "10-20%", "30-40%", "80-90%"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le phytoplancton marin, via la photosynthèse, génère entre 50 et 70 % de l'oxygène atmosphérique, ce qui fait des océans le principal poumon de la planète."),
        Question(30185, "Combien d'espèces reconnues de récifs coralliens existent ?", listOf("Plus de 800", "Plus de 200", "Plus de 1000", "Plus de 500"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les scientifiques recensent plus de 800 espèces de coraux durs constructeurs de récifs, principalement dans les eaux chaudes et peu profondes des océans tropicaux."),
        Question(30186, "Quel animal a le cou le plus long de tous les êtres vivants ?", listOf("Girafe", "Autruche", "Lama", "Émeu"), 0, "Nature", Difficulty.MEDIUM, explanation = "La girafe possède le cou le plus long de tous les animaux vivants, mesurant jusqu'à 2,4 mètres, ce qui lui permet d'atteindre les feuilles hautes des arbres dans la savane africaine."),
        Question(30187, "Quelle est la partie la plus profonde de l'océan ?", listOf("Fosse des Mariannes", "Fosse de Tonga", "Fosse des Philippines", "Fosse Kourilo-Kamtchatka"), 0, "Nature", Difficulty.MEDIUM, explanation = "La fosse des Mariannes, située dans l'océan Pacifique, atteint environ 11 034 mètres de profondeur à son point le plus bas, le Challenger Deep."),
        Question(30188, "Quelle espèce d'oiseau est la plus grande en poids ?", listOf("Autruche", "Émeu", "Casoar", "Nandou"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'autruche est l'oiseau le plus lourd au monde, avec un poids pouvant atteindre 150 kg, ce qui la rend incapable de voler mais très rapide à la course."),
        Question(30189, "Quelle est la cause principale de la déforestation en Amazonie ?", listOf("Élevage de bétail", "Exploitation forestière", "Exploitation minière", "Agriculture"), 0, "Nature", Difficulty.HARD, explanation = "L'élevage de bétail est la première cause de déforestation en Amazonie, car d'immenses surfaces sont défrichées pour créer des pâturages destinés à l'industrie de la viande."),
        Question(30190, "Combien d'espèces s'éteignent par jour à cause de l'activité humaine ?", listOf("137", "50", "200", "300"), 0, "Nature", Difficulty.HARD, explanation = "Selon l'Union internationale pour la conservation de la nature, l'activité humaine provoque l'extinction d'environ 137 espèces par jour, principalement à cause de la destruction des habitats et du changement climatique."),
        Question(30191, "De quoi est composée la Grande Barrière de Corail ?", listOf("Polypes de corail", "Pierre", "Coquilles", "Algues"), 0, "Nature", Difficulty.HARD, explanation = "La Grande Barrière de Corail est un vaste écosystème formé par des colonies de polypes de corail, de petits animaux marins qui sécrètent un squelette calcaire."),
        Question(30193, "Qu'est-ce que la 'bioluminescence' ?", listOf("Lumière produite par les organismes vivants", "Chaleur des organismes", "Mouvement des organismes", "Changement de couleur des organismes"), 0, "Nature", Difficulty.HARD, explanation = "La bioluminescence est un phénomène chimique où des êtres vivants, comme les lucioles ou certains poissons des profondeurs, produisent de la lumière grâce à une réaction entre une luciférine et une enzyme."),
        Question(30194, "Quelle est la profondeur de la zone euphotique dans l'océan ?", listOf("200 mètres", "1000 mètres", "500 mètres", "50 mètres"), 0, "Nature", Difficulty.HARD, explanation = "La zone euphotique, où la lumière solaire pénètre suffisamment pour permettre la photosynthèse, s'étend en moyenne jusqu'à 200 mètres de profondeur dans l'océan."),
        Question(30195, "Quel est l'âge estimé du Grand Canyon ?", listOf("6 millions d'années", "2 millions d'années", "10 millions d'années", "1 million d'années"), 0, "Nature", Difficulty.HARD, explanation = "Le Grand Canyon a commencé à se former il y a environ 6 millions d'années sous l'action érosive du fleuve Colorado. Cette estimation repose sur des datations de roches et de dépôts sédimentaires."),
        Question(30196, "Quel animal a le plus de dents parmi tous les mammifères ?", listOf("Dauphin", "Éléphant", "Baleine", "Hippopotame"), 0, "Nature", Difficulty.EXPERT, explanation = "Le dauphin peut avoir jusqu'à 250 dents, ce qui en fait le mammifère avec le plus grand nombre de dents. Ces dents servent principalement à attraper et retenir leurs proies glissantes."),
        Question(30197, "Quel est le résultat scientifique de l'équation de photosynthèse CO2+H2O ?", listOf("C6H12O6 + O2", "CH4 + O", "C2H6 + O2", "C3H8 + O"), 0, "Nature", Difficulty.EXPERT, explanation = "L'équation de la photosynthèse convertit le dioxyde de carbone et l'eau en glucose (C6H12O6) et en oxygène (O2) grâce à l'énergie lumineuse."),
        Question(30198, "Combien d'espèces de poissons sont estimées exister dans le monde ?", listOf("30000-35000", "5000-10000", "50000-60000", "100000+"), 0, "Nature", Difficulty.EXPERT, explanation = "Les océans et eaux douces abritent entre 30 000 et 35 000 espèces de poissons identifiées, mais les scientifiques estiment que ce nombre pourrait atteindre 40 000 avec les découvertes futures."),
        Question(30199, "Quel pourcentage de la forêt tropicale amazonienne a été défriché depuis 1970 ?", listOf("17%", "5%", "30%", "50%"), 0, "Nature", Difficulty.EXPERT, explanation = "Depuis 1970, environ 17% de la forêt amazonienne a été défriché, principalement à cause de l'expansion agricole et de l'exploitation forestière."),
        Question(30200, "Quel organisme a le plus petit ratio cerveau-corps ?", listOf("Baleine bleue", "Éléphant", "Humain", "Pieuvre"), 0, "Nature", Difficulty.EXPERT, explanation = "Malgré son cerveau de près de 7 kg, la baleine bleue possède le plus petit ratio cerveau-corps du règne animal, son corps pouvant peser jusqu'à 200 tonnes."),

        // SCIENCE (30201-30225) - 25 questions
        Question(30202, "Quelle est la vitesse de la lumière ?", listOf("300 000 km/s", "150 000 km/s", "500 000 km/s", "100 000 km/s"), 0, "Science", Difficulty.EASY, explanation = "C'est la valeur approximative de la vitesse de la lumière dans le vide, une constante fondamentale de la physique notée c."),
        Question(30203, "Combien d'os un corps humain adulte a-t-il ?", listOf("206", "250", "186", "300"), 0, "Science", Difficulty.EASY, explanation = "Le squelette humain adulte est composé de 206 os, un nombre qui peut varier légèrement selon les individus en raison de la fusion de certains os avec l'âge."),
        Question(30204, "Quel est l'élément le plus abondant de l'univers ?", listOf("Hydrogène", "Hélium", "Carbone", "Oxygène"), 0, "Science", Difficulty.EASY, explanation = "L'hydrogène est l'élément le plus abondant de l'univers, représentant environ 75% de sa masse baryonique, car il a été le premier élément formé après le Big Bang."),
        Question(30205, "Quel est la centrale énergétique de la cellule ?", listOf("Mitochondrie", "Noyau", "Ribosome", "Appareil de Golgi"), 0, "Science", Difficulty.EASY, explanation = "Les mitochondries sont les organites cellulaires responsables de la production d'énergie sous forme d'ATP via la respiration cellulaire."),
        Question(30206, "Combien de planètes sont dans notre système solaire ?", listOf("8", "9", "10", "7"), 0, "Science", Difficulty.EASY, explanation = "En 2006, l'Union astronomique internationale a reclassé Pluton en planète naine, ramenant officiellement le nombre de planètes majeures du système solaire à huit."),
        Question(30207, "Qui a développé la théorie de l'évolution par sélection naturelle ?", listOf("Charles Darwin", "Alfred Wallace", "Jean-Baptiste Lamarck", "Gregor Mendel"), 0, "Science", Difficulty.MEDIUM, explanation = "Charles Darwin a formulé cette théorie après ses observations lors du voyage du Beagle, notamment aux îles Galápagos. Son ouvrage \"L'Origine des espèces\" (1859) a révolutionné la biologie."),
        Question(30208, "Quel est le nom complet de l'ADN ?", listOf("Acide désoxyribonucléique", "Acide déoxynucléique", "Acide désoxyribose", "Acide diribonucléique"), 0, "Science", Difficulty.MEDIUM, explanation = "L'ADN est l'abréviation d'acide désoxyribonucléique, une molécule qui contient l'information génétique de tous les êtres vivants."),
        Question(30209, "Combien d'éléments sont dans le tableau périodique ?", listOf("118", "100", "90", "150"), 0, "Science", Difficulty.MEDIUM, explanation = "Le tableau périodique standard contient 118 éléments confirmés, allant de l'hydrogène (1) à l'oganesson (118)."),
        Question(30211, "Quel est le processus par lequel les plantes convertissent la lumière solaire en énergie ?", listOf("Photosynthèse", "Respiration", "Fermentation", "Transpiration"), 0, "Science", Difficulty.MEDIUM, explanation = "La photosynthèse est le processus biologique par lequel les plantes, les algues et certaines bactéries utilisent la lumière du soleil pour transformer le dioxyde de carbone et l'eau en glucose et en oxygène."),
        Question(30212, "Quel est le nom de l'étoile la plus proche de la Terre (en dehors du Soleil) ?", listOf("Proxima Centauri", "Alpha Centauri", "Sirius", "Bételgeuse"), 0, "Science", Difficulty.MEDIUM, explanation = "Proxima Centauri fait partie du système stellaire Alpha Centauri, situé à environ 4,2 années-lumière de la Terre, ce qui en fait l'étoile la plus proche après le Soleil."),
        Question(30213, "Quel type de globule blanc est responsable de combattre les infections ?", listOf("Globules blancs", "Globules rouges", "Plaquettes", "Lymphocytes"), 0, "Science", Difficulty.MEDIUM, explanation = "Les globules blancs, ou leucocytes, sont les cellules du système immunitaire qui détectent et détruisent les agents pathogènes comme les bactéries et virus."),
        Question(30214, "Quel est le point de congélation de l'eau en Celsius ?", listOf("0°C", "-4°C", "4°C", "-273°C"), 0, "Science", Difficulty.HARD, explanation = "L'eau pure gèle à 0°C sous pression atmosphérique normale, car c'est la température à laquelle ses molécules forment une structure cristalline solide."),
        Question(30215, "Qui a formulé la théorie de la relativité ?", listOf("Albert Einstein", "Isaac Newton", "Max Planck", "Niels Bohr"), 0, "Science", Difficulty.HARD, explanation = "Albert Einstein a publié la théorie de la relativité restreinte en 1905, puis la relativité générale en 1915, révolutionnant la compréhension de l'espace, du temps et de la gravitation."),
        Question(30216, "Quel est le nom de la plus petite unité de matière qui conserve les propriétés chimiques ?", listOf("Atome", "Molécule", "Électron", "Noyau"), 0, "Science", Difficulty.HARD, explanation = "L'atome est la plus petite unité d'un élément chimique qui conserve ses propriétés, car il est composé d'un noyau et d'électrons."),
        Question(30217, "Quel est le processus par lequel une étoile devient un trou noir ?", listOf("Effondrement gravitationnel", "Fusion nucléaire", "Explosion de supernova", "Refroidissement de naine blanche"), 0, "Science", Difficulty.HARD, explanation = "L'effondrement gravitationnel se produit lorsque le noyau d'une étoile massive n'a plus assez d'énergie pour contrer sa propre gravité après l'épuisement de son combustible nucléaire, ce qui la comprime en un point de densité infinie."),
        Question(30218, "Combien de chambres le cœur humain a-t-il ?", listOf("4", "3", "5", "6"), 0, "Science", Difficulty.HARD, explanation = "Le cœur humain est divisé en quatre cavités : deux oreillettes et deux ventricules, qui assurent la circulation sanguine dans l'organisme."),
        Question(30219, "Quelle est la demi-vie du Carbone-14 ?", listOf("5 730 ans", "1 000 ans", "10 000 ans", "50 000 ans"), 0, "Science", Difficulty.HARD, explanation = "Le Carbone-14 est un isotope radioactif du carbone dont la demi-vie, soit le temps nécessaire pour que la moitié des atomes se désintègre, est de 5 730 ans, ce qui permet la datation d'échantillons organiques anciens."),
        Question(30220, "Quel est le composant principal du Soleil ?", listOf("Hydrogène", "Hélium", "Oxygène", "Carbone"), 0, "Science", Difficulty.HARD, explanation = "Le Soleil est une étoile composée à environ 73% d'hydrogène, qui fusionne en hélium dans son noyau pour produire de l'énergie."),
        Question(30221, "À quoi la constante de Planck est-elle utilisée pour mesurer ?", listOf("Quantum d'action", "Vitesse de la lumière", "Constante gravitationnelle", "Charge électrique"), 0, "Science", Difficulty.EXPERT, explanation = "La constante de Planck, notée h, relie l'énergie d'un photon à sa fréquence et définit le quantum d'action, une unité fondamentale en mécanique quantique."),
        Question(30222, "Quel est le nom de la première exoplanète découverte autour d'une étoile semblable au Soleil ?", listOf("51 Pegasi b", "Kepler-452b", "TRAPPIST-1e", "HD 209458 b"), 0, "Science", Difficulty.EXPERT, explanation = "Découverte en 1995 par Michel Mayor et Didier Queloz, 51 Pegasi b orbite autour de l'étoile 51 Pegasi, une naine jaune similaire au Soleil. Cette détection a révolutionné l'astronomie en prouvant l'existence de planètes hors du système solaire."),
        Question(30223, "De quoi le boson de Higgs est-il responsable ?", listOf("Donner la masse aux particules", "Force électromagnétique", "Force nucléaire forte", "Gravité"), 0, "Science", Difficulty.EXPERT, explanation = "Le boson de Higgs interagit avec certaines particules élémentaires via le champ de Higgs, et cette interaction leur confère une masse. Sans ce mécanisme, les particules comme les électrons ou les quarks n'auraient pas de masse."),
        Question(30224, "Quel est le nom de la protéine qui transporte l'oxygène dans les globules rouges ?", listOf("Hémoglobine", "Myoglobine", "Albumine", "Globuline"), 0, "Science", Difficulty.EXPERT, explanation = "L'hémoglobine est une protéine complexe contenant du fer, située dans les globules rouges, qui fixe l'oxygène dans les poumons pour le distribuer aux tissus du corps."),
        Question(30225, "Combien d'acides aminés sont essentiels à la synthèse des protéines humaines ?", listOf("20", "9", "15", "25"), 0, "Science", Difficulty.EXPERT, explanation = "Les protéines humaines sont synthétisées à partir de 20 acides aminés différents, dont 9 sont dits essentiels car le corps ne peut pas les produire lui-même."),

        // MYTHOLOGIE (30226-30250) - 25 questions
        Question(30226, "Qui est le roi des dieux grecs ?", listOf("Zeus", "Hadès", "Poséidon", "Apollon"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, Zeus est le dieu du ciel et de la foudre, souverain de l'Olympe après avoir renversé son père Cronos."),
        Question(30227, "Quel est le rôle équivalent d'Odin dans la mythologie nordique ?", listOf("Roi des dieux", "Dieu de la guerre", "Dieu du tonnerre", "Dieu de la mer"), 0, "Mythologie", Difficulty.EASY, explanation = "Odin est le dieu principal et le souverain des Ases dans la mythologie nordique, comparable à Zeus dans la mythologie grecque."),
        Question(30228, "Qui est le dieu égyptien du soleil ?", listOf("Ra", "Osiris", "Thot", "Anubis"), 0, "Mythologie", Difficulty.EASY, explanation = "Ra est le dieu solaire principal de la mythologie égyptienne antique, souvent représenté avec une tête de faucon surmontée d'un disque solaire."),
        Question(30229, "Quelle est l'arme de Thor dans la mythologie nordique ?", listOf("Mjölnir", "Gungnir", "Skadhka", "Gleipnir"), 0, "Mythologie", Difficulty.EASY, explanation = "Mjölnir est le marteau forgé par les nains Brokk et Sindri, capable de provoquer la foudre et de revenir dans la main de Thor après avoir été lancé."),
        Question(30230, "Dans la mythologie hindoue, qui est le dieu de la destruction ?", listOf("Shiva", "Brahma", "Vishnu", "Indra"), 0, "Mythologie", Difficulty.EASY, explanation = "Shiva est l'une des divinités principales de l'hindouisme, formant la Trimurti avec Brahma (créateur) et Vishnu (protecteur). Son rôle de destructeur permet la renaissance et le renouvellement de l'univers."),
        Question(30231, "Quel est le nom des enfers égyptiens ?", listOf("Duat", "Aaru", "Tuat", "Sekhet"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie égyptienne, le Duat est le royaume des morts, un monde souterrain traversé par le dieu solaire Rê chaque nuit et où l'âme du défunt est jugée par Osiris."),
        Question(30232, "Qui a créé le monde selon la mythologie aztèque ?", listOf("Quetzalcoatl", "Tezcatlipoca", "Huitzilopochtli", "Ometeotl"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie aztèque, Quetzalcoatl, le serpent à plumes, est l'un des dieux créateurs qui participa à la création du monde actuel, notamment en façonnant l'humanité à partir d'os."),
        Question(30233, "Quel est le nom de l'épouse de Poséidon dans la mythologie grecque ?", listOf("Amphitrite", "Héra", "Thétis", "Néréide"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Amphitrite est une Néréide, déesse de la mer, et l'épouse légitime de Poséidon dans la mythologie grecque."),
        Question(30234, "Dans la mythologie celtique, qui est le dieu du soleil et de la poésie ?", listOf("Lugh", "Dagda", "Nuada", "Morrigan"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Lugh est une divinité majeure du panthéon celtique, souvent associée à la lumière, aux arts et aux compétences multiples, dont la poésie."),
        Question(30235, "Quel est le nom de la déesse du soleil japonaise ?", listOf("Amaterasu", "Susanoo", "Izanami", "Tsukuyomi"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Amaterasu est la déesse du soleil dans le shintoïsme, religion traditionnelle du Japon. Elle est considérée comme l'ancêtre de la famille impériale japonaise."),
        Question(30236, "Dans la mythologie africaine, qu'est-ce qu'Amma ?", listOf("Divinité créatrice dans la tradition Dogon", "Dieu des tricheurs", "Déesse de la guerre", "Esprit de l'eau"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Amma est le dieu créateur dans la cosmogonie du peuple Dogon, au Mali, qui aurait façonné l'univers et les humains."),
        Question(30237, "Quel est le rôle de l'Empereur de Jade chinois ?", listOf("Souverain du ciel et de la terre", "Dieu de la guerre", "Dieu de la richesse", "Gardien des âmes"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie chinoise, l'Empereur de Jade est la divinité suprême qui gouverne le ciel, la terre et tous les dieux, comparable à un empereur céleste."),
        Question(30238, "Dans la mythologie mésopotamienne, qui est le roi des dieux ?", listOf("Marduk", "Enlil", "Enki", "Anu"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Marduk est le dieu principal de la mythologie mésopotamienne, notamment à Babylone, où il devient roi des dieux après avoir vaincu le chaos primordial représenté par Tiamat."),
        Question(30239, "Quel est le nom du héros grec qui a tué le Minotaure ?", listOf("Thésée", "Héraclès", "Jason", "Persée"), 0, "Mythologie", Difficulty.HARD, explanation = "Thésée a tué le Minotaure dans le labyrinthe de Crète, aidé par le fil d'Ariane pour en ressortir."),
        Question(30240, "Dans la mythologie hindoue, de quoi parle le Ramayana ?", listOf("La quête de Rama", "La danse de Shiva", "La naissance de Krishna", "La guerre des dieux"), 0, "Mythologie", Difficulty.HARD, explanation = "Le Ramayana relate l'histoire du prince Rama, avatar de Vishnou, qui part à la recherche de son épouse Sita, enlevée par le démon Ravana."),
        Question(30241, "Qu'est-ce que Yggdrasil dans la mythologie nordique ?", listOf("L'arbre du monde", "Le pont vers les dieux", "Le serpent du chaos", "Le palais des dieux"), 0, "Mythologie", Difficulty.HARD, explanation = "Yggdrasil est l'arbre cosmique qui relie les neuf mondes de la mythologie nordique, ses racines et branches soutenant l'univers."),
        Question(30242, "Dans la mythologie égyptienne, que arrive-t-il à une âme après la mort ?", listOf("Pesée du cœur dans le Duat", "Réincarnation", "Ascension au ciel", "Sommeil éternel"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie égyptienne, l'âme du défunt est jugée dans le Duat lors de la pesée du cœur contre la plume de Maât, déterminant son accès à l'au-delà."),
        Question(30243, "Qui est le dieu tricheur dans la mythologie nordique ?", listOf("Loki", "Odin", "Thor", "Heimdall"), 0, "Mythologie", Difficulty.HARD, explanation = "Loki est une divinité ambiguë de la mythologie nordique, souvent représentée comme un farceur et un manipulateur, capable de changer de forme pour tromper les autres dieux."),
        Question(30244, "Dans la mythologie aztèque, qu'est-ce que le Cinquième Soleil ?", listOf("L'âge du monde actuel", "Cataclysme futur", "Création passée", "Monde souterrain"), 0, "Mythologie", Difficulty.HARD, explanation = "Selon la mythologie aztèque, le monde a connu quatre soleils (âges) précédents, chacun détruit par une catastrophe. Le Cinquième Soleil désigne l'ère actuelle, celle des humains, créée par le sacrifice des dieux à Teotihuacan."),
        Question(30245, "Quel est le nom des enfers chinois ?", listOf("Diyu", "Yomi", "Hadès", "Monde souterrain"), 0, "Mythologie", Difficulty.HARD, explanation = "Diyu désigne l'enfer bouddhiste et taoïste chinois, un monde souterrain où les âmes sont jugées et purifiées avant leur réincarnation."),
        Question(30246, "Dans la mythologie hindoue, que sont les Vedas ?", listOf("Textes sacrés anciens", "Demi-dieux", "Êtres célestes", "Incantations"), 0, "Mythologie", Difficulty.EXPERT, explanation = "Les Vedas sont les plus anciens textes sacrés de l'hindouisme, comprenant des hymnes, des rituels et des enseignements philosophiques."),
        Question(30247, "Qu'est-ce que la Chimère dans la mythologie grecque ?", listOf("Un monstre hybride avec lion, chèvre et serpent", "Une créature marine", "Un cheval ailé", "Un géant de feu"), 0, "Mythologie", Difficulty.EXPERT, explanation = "La Chimère était un monstre cracheur de feu, décrit comme ayant une tête de lion, un corps de chèvre et une queue de serpent, vaincue par le héros Bellérophon monté sur Pégase."),
        Question(30248, "Dans la mythologie mésopotamienne, qui est le héros du déluge ?", listOf("Atrahasis", "Gilgamesh", "Enkidu", "Shamash"), 0, "Mythologie", Difficulty.EXPERT, explanation = "Atrahasis est le héros du déluge dans la mythologie mésopotamienne, apparaissant dans l'épopée éponyme sumérienne. Ce récit, antérieur à l'épopée de Gilgamesh, raconte comment le dieu Enki avertit Atrahasis du déluge envoyé par les dieux."),
        Question(30249, "Qu'est-ce que l'Ouroboros dans la mythologie ?", listOf("Un serpent se mangeant la queue", "Un œuf cosmique", "Un arbre du monde", "Une forge divine"), 0, "Mythologie", Difficulty.EXPERT, explanation = "L'Ouroboros est un symbole ancien représentant un serpent ou un dragon qui se mord la queue, illustrant le cycle éternel de la vie, de la mort et de la renaissance."),
        Question(30250, "Dans la mythologie hindoue, comment s'appelle la danse cosmique de Shiva ?", listOf("Tandava", "Rasa", "Lila", "Puja"), 0, "Mythologie", Difficulty.EXPERT, explanation = "Le Tandava est la danse cosmique de Shiva, symbolisant à la fois la création et la destruction de l'univers."),

        // HISTOIRE (30251-30275) - 25 questions
        Question(30251, "En quelle année la Deuxième Guerre mondiale s'est-elle terminée ?", listOf("1945", "1943", "1947", "1940"), 0, "Histoire", Difficulty.EASY, explanation = "La Seconde Guerre mondiale a pris fin en 1945 avec la capitulation de l'Allemagne nazie en mai et celle du Japon en septembre."),
        Question(30252, "Qui a été le premier Président des États-Unis ?", listOf("George Washington", "Thomas Jefferson", "John Adams", "Benjamin Franklin"), 0, "Histoire", Difficulty.EASY, explanation = "George Washington a été le premier président des États-Unis, élu en 1789 après avoir dirigé l'armée continentale pendant la guerre d'indépendance."),
        Question(30254, "Quel empire a construit la Grande Muraille de Chine ?", listOf("Dynastie Ming", "Dynastie Tang", "Dynastie Zhou", "Dynastie Han"), 0, "Histoire", Difficulty.EASY, explanation = "Bien que des fortifications existaient depuis le IIIe siècle av. J.-C., la majeure partie de la Grande Muraille visible aujourd'hui a été construite sous la dynastie Ming (1368-1644) pour se protéger des invasions mongoles."),
        Question(30255, "En quelle année le Titanic a-t-il coulé ?", listOf("1912", "1915", "1910", "1920"), 0, "Histoire", Difficulty.EASY, explanation = "Le Titanic a coulé le 15 avril 1912 lors de son voyage inaugural, après avoir heurté un iceberg dans l'Atlantique Nord."),
        Question(30256, "Qui a été le premier Président de la France ?", listOf("Napoléon Bonaparte", "Louis-Napoléon Bonaparte", "Charles de Gaulle", "Georges Clemenceau"), 0, "Histoire", Difficulty.EASY, explanation = "Napoléon Bonaparte a été le premier président de la France, élu en 1848 sous la Deuxième République, avant de devenir empereur."),
        Question(30258, "Qui était l'empereur romain connu pour avoir construit le Colosseum ?", listOf("Vespasien", "Auguste", "Néron", "Trajan"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Vespasien a ordonné la construction du Colisée, achevé sous son fils Titus, pour offrir des spectacles au peuple romain après les guerres civiles."),
        Question(30259, "Qu'était la Route de la Soie ?", listOf("Voie commerciale reliant l'Est et l'Ouest", "Route militaire", "Itinéraire de pèlerinage religieux", "Voie maritime"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La Route de la Soie était un réseau de routes commerciales terrestres et maritimes qui reliait la Chine à la Méditerranée, facilitant les échanges de marchandises comme la soie, les épices et les idées entre l'Est et l'Ouest."),
        Question(30260, "Quel Sultan ottoman a conquis Constantinople en 1453 ?", listOf("Mehmed II", "Soliman I", "Mourad II", "Orkhan"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Mehmed II, dit le Conquérant, mit fin à l'Empire byzantin en prenant Constantinople après un siège de 53 jours, utilisant des canons géants et une flotte."),
        Question(30261, "Qui a dirigé l'Empire mongol à son apogée ?", listOf("Gengis Khan", "Koubilaï Khan", "Tamerlan", "Möngke Khan"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Gengis Khan a unifié les tribus mongoles et fondé l'Empire mongol au début du XIIIe siècle, le menant à son extension maximale à sa mort en 1227."),
        Question(30262, "En quelle année Colomb a-t-il atteint les Amériques ?", listOf("1492", "1500", "1485", "1510"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Christophe Colomb, naviguant sous pavillon espagnol, atteint les Amériques le 12 octobre 1492, croyant avoir trouvé une route vers l'Asie."),
        Question(30263, "Qui a été l'architecte de la Terreur pendant la Révolution française ?", listOf("Robespierre", "Danton", "Marat", "Carnot"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Maximilien de Robespierre, figure majeure des Jacobins, a dirigé le Comité de salut public et instauré la Terreur pour réprimer les opposants à la Révolution."),
        Question(30264, "Sur quel continent l'Empire du Mali a-t-il prospéré ?", listOf("Afrique", "Asie", "Amérique du Sud", "Europe"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire du Mali était un puissant royaume médiéval situé en Afrique de l'Ouest, connu pour sa richesse en or et son influence culturelle."),
        Question(30265, "Quelle était la cause principale de la chute de l'Empire romain ?", listOf("Invasions barbares et conflits internes", "Épidémies", "Effondrement économique seul", "Catastrophe naturelle"), 0, "Histoire", Difficulty.HARD, explanation = "Les invasions barbares, combinées aux guerres civiles et à l'instabilité politique, ont affaibli l'empire jusqu'à sa chute en 476."),
        Question(30266, "Quel royaume africain était connu pour contrôler le commerce de l'or et du sel ?", listOf("Empire du Ghana", "Songhaï", "Éthiopie", "Congo"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire du Ghana, situé dans l'actuelle Afrique de l'Ouest, a prospéré entre le VIIIe et le XIe siècle en contrôlant les routes commerciales transsahariennes de l'or et du sel."),
        Question(30267, "En quelle année la Guerre de Sécession américaine a-t-elle commencé ?", listOf("1861", "1860", "1863", "1865"), 0, "Histoire", Difficulty.HARD, explanation = "La guerre de Sécession a débuté le 12 avril 1861 avec l'attaque confédérée sur Fort Sumter en Caroline du Sud, marquant le premier affrontement armé entre les États du Nord et du Sud."),
        Question(30268, "Qui a été le premier Empereur du Japon ?", listOf("Jimmu", "Suiko", "Shotoku", "Kangaku"), 0, "Histoire", Difficulty.HARD, explanation = "Jimmu est considéré comme le fondateur légendaire du Japon et le premier empereur, selon la tradition impériale nippone. Son règne mythique aurait débuté en 660 avant J.-C."),
        Question(30269, "Quelle était la motivation principale de l'exploration européenne aux 15e-16e siècles ?", listOf("Épices, or et routes commerciales", "Découverte scientifique", "Conversion religieuse", "Conquête territoriale"), 0, "Histoire", Difficulty.HARD, explanation = "Les épices asiatiques, l'or africain et le contrôle des routes commerciales vers l'Orient motivaient les puissances européennes, contournant les intermédiaires ottomans et vénitiens."),
        Question(30270, "Quel empire sud-américain a été conquis par Pizarro ?", listOf("Inca", "Aztèque", "Maya", "Muisca"), 0, "Histoire", Difficulty.HARD, explanation = "Francisco Pizarro a conquis l'Empire inca dans les années 1530, capturant son empereur Atahualpa. Cette conquête a marqué la chute du plus grand empire précolombien d'Amérique du Sud."),
        Question(30271, "En quelle année la Révolution russe s'est-elle produite ?", listOf("1917", "1915", "1920", "1905"), 0, "Histoire", Difficulty.EXPERT, explanation = "La Révolution russe a eu lieu en 1917, marquée par deux soulèvements : la révolution de Février qui a renversé le tsar, puis la révolution d'Octobre menée par les bolcheviks."),
        Question(30272, "Qui a été l'architecte de la Restauration Meiji au Japon ?", listOf("Empereur Meiji", "Tokugawa Ieyasu", "Oda Nobunaga", "Toyotomi Hideyoshi"), 0, "Histoire", Difficulty.EXPERT, explanation = "L'empereur Meiji a dirigé la modernisation rapide du Japon après 1868, mettant fin au shogunat et centralisant le pouvoir impérial pour transformer le pays en puissance industrielle et militaire."),
        Question(30273, "Quelle était la signification du Traité de Westphalie (1648) ?", listOf("Établissement du système d'État-nation moderne", "Fin des Croisades", "Abolition du féodalisme", "Création de l'UE"), 0, "Histoire", Difficulty.EXPERT, explanation = "Le Traité de Westphalie a mis fin à la guerre de Trente Ans en reconnaissant la souveraineté des États sur leur territoire, posant ainsi les bases du système d'État-nation moderne."),
        Question(30274, "Qui a fondé l'Empire Safavide et établi l'islam chiite comme religion d'État ?", listOf("Ismail I", "Abbas I", "Tahmasp I", "Cyrus le Grand"), 0, "Histoire", Difficulty.EXPERT, explanation = "Ismail Ier, chef de l'ordre soufi des Safavides, conquit la Perse au début du XVIe siècle et proclama le chiisme duodécimain religion d'État en 1501."),
        Question(30275, "Qu'était la Partition de l'Inde en 1947 principalement ?", listOf("Division en Inde et Pakistan", "Indépendance de la Grande-Bretagne", "Création du Bangladesh", "Résolution de conflits religieux"), 0, "Histoire", Difficulty.EXPERT, explanation = "La Partition de l'Inde en 1947 a divisé le Raj britannique en deux États indépendants, l'Inde à majorité hindoue et le Pakistan à majorité musulmane, suite aux tensions religieuses et à la fin de la colonisation britannique."),

        // PHILOSOPHIE (30276-30300) - 25 questions
        Question(30276, "Quel philosophe est connu pour avoir dit 'Je pense, donc je suis' ?", listOf("René Descartes", "Immanuel Kant", "Friedrich Nietzsche", "Jean-Paul Sartre"), 0, "Philosophie", Difficulty.EASY, explanation = "René Descartes énonce cette formule dans son Discours de la méthode (1637) comme première certitude après avoir douté de tout, fondant ainsi la philosophie moderne sur le sujet pensant."),
        Question(30277, "En quoi consiste fondamentalement le stoïcisme ?", listOf("Vertu et acceptation du destin", "Plaisir et bonheur", "Connaissance et raison", "Devoir et obligation"), 0, "Philosophie", Difficulty.EASY, explanation = "Le stoïcisme enseigne que le bonheur réside dans la vertu, seule chose sous notre contrôle, et dans l'acceptation sereine des événements extérieurs, dictés par le destin ou la nature."),
        Question(30278, "Qui a écrit 'Cent ans de solitude' ?", listOf("Gabriel García Márquez", "Jorge Luis Borges", "Pablo Neruda", "Octavio Paz"), 0, "Philosophie", Difficulty.EASY, explanation = "Gabriel García Márquez, écrivain colombien, a publié ce roman majeur du réalisme magique en 1967, qui lui a valu le prix Nobel de littérature en 1982."),
        Question(30279, "Quel mouvement philosophique a souligné le doute et le questionnement ?", listOf("Scepticisme", "Dogmatisme", "Relativisme", "Empirisme"), 0, "Philosophie", Difficulty.EASY, explanation = "Le scepticisme, courant philosophique antique, place le doute méthodique et le questionnement permanent au cœur de sa démarche pour atteindre la sagesse."),
        Question(30280, "Qui est connu comme le père de la philosophie occidentale ?", listOf("Socrate", "Platon", "Aristote", "Pythagore"), 0, "Philosophie", Difficulty.EASY, explanation = "Socrate est considéré comme le père de la philosophie occidentale car il a introduit la méthode dialectique et a influencé des penseurs majeurs comme Platon et Aristote."),
        Question(30281, "Qu'est-ce que l'existentialisme souligne ?", listOf("Liberté individuelle et choix", "Volonté divine", "Raison et logique", "Devoir social"), 0, "Philosophie", Difficulty.EASY, explanation = "L'existentialisme, courant philosophique du XXe siècle, affirme que l'existence précède l'essence, plaçant la liberté individuelle et le choix au cœur de la condition humaine."),
        Question(30283, "Quelle est l'idée centrale de la Théorie des Formes de Platon ?", listOf("Des universaux abstraits idéaux existent au-delà du monde physique", "La réalité est seulement physique", "Toute connaissance est relative", "La vérité est subjective"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Platon distingue le monde sensible, imparfait et changeant, d'un monde intelligible parfait et immuable, où résident les Formes (ou Idées), comme le Beau ou le Juste, qui sont les modèles des choses physiques."),
        Question(30284, "Qui a écrit '1984' et 'La Ferme des animaux' ?", listOf("George Orwell", "Aldous Huxley", "Margaret Atwood", "Ray Bradbury"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "George Orwell, de son vrai nom Eric Arthur Blair, est l'auteur de ces deux romans dystopiques et satiriques majeurs du XXe siècle."),
        Question(30285, "Quel est la principale préoccupation de l'éthique ?", listOf("Comment vivre une bonne vie", "La nature de la réalité", "Comment la connaissance est acquise", "L'origine de l'univers"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "L'éthique se concentre sur les principes guidant les actions humaines, et sa question fondamentale est de déterminer ce qui constitue une existence épanouissante et moralement juste."),
        Question(30286, "Quel auteur japonais a écrit 'Norwegian Wood' et 'Kafka sur le rivage' ?", listOf("Haruki Murakami", "Yukio Mishima", "Yasunari Kawabata", "Kenzaburo Oe"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Haruki Murakami est un écrivain japonais contemporain mondialement reconnu, dont les romans 'Norwegian Wood' (1987) et 'Kafka sur le rivage' (2002) figurent parmi ses œuvres les plus célèbres."),
        Question(30287, "Comment le pragmatisme juge-t-il la vérité ?", listOf("Par les conséquences pratiques et l'utilité", "Par la cohérence logique", "Par la correspondance à la réalité", "Par les principes universels"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Pour le pragmatisme, une idée est vraie si elle fonctionne dans la pratique et produit des résultats utiles, contrairement aux théories qui la définissent par la correspondance avec la réalité."),
        Question(30288, "Qui a écrit 'Le Deuxième Sexe', un texte fondateur du féminisme ?", listOf("Simone de Beauvoir", "Betty Friedan", "Gloria Steinem", "Germaine Greer"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Simone de Beauvoir a publié 'Le Deuxième Sexe' en 1949, une analyse existentialiste de la condition féminine qui a posé les bases du féminisme moderne."),
        Question(30289, "Quel concept philosophique est attribué à Arthur Schopenhauer ?", listOf("Le monde comme volonté et représentation", "L'impératif catégorique", "La volonté de puissance", "L'être et le néant"), 0, "Philosophie", Difficulty.HARD, explanation = "Schopenhauer expose sa philosophie dans son œuvre majeure *Le monde comme volonté et représentation*, où il affirme que la volonté est la force fondamentale de la réalité."),
        Question(30290, "Qui a développé le concept du 'Bon Sauvage' ?", listOf("Jean-Jacques Rousseau", "Thomas Hobbes", "John Locke", "David Hume"), 0, "Philosophie", Difficulty.HARD, explanation = "Rousseau a développé ce concept dans son Discours sur l'origine et les fondements de l'inégalité parmi les hommes, où il idéalise l'état de nature de l'homme avant la civilisation."),
        Question(30291, "Quel est le thème principal du 'Crime et Châtiment' de Fyodor Dostoyevski ?", listOf("Moralité, culpabilité et rédemption", "Révolution sociale", "Amour et trahison", "Folie et santé"), 0, "Philosophie", Difficulty.HARD, explanation = "Le roman suit Raskolnikov, un étudiant qui assassine une usurière et lutte ensuite avec sa conscience. Dostoyevski explore les conséquences psychologiques du crime et la quête de rédemption morale."),
